sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 parallax;
uniform float2 offset;
uniform float strength;
uniform float evolution;
uniform float direction;
uniform float scale;
uniform float2 stretch;
uniform float seed;
uniform float octaves;
uniform float bias;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
float fbm(float3 p, float octaves, float2 drift, float gain) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 9; i++) {
        if (float(i) >= octaves) break;
        sum += amp * vnoise(p);
        norm += amp;
        amp *= gain;
        p = float3(p.xy * 2.03 + drift + float2(17.13, 9.71), p.z * 1.7 + 3.1);
    }
    return sum / max(norm, 0.0001);
}
half4 main(float2 coord) {
    float unit = 0.4 * size.y * max(scale, 0.01);
    float2 rel = coord - size * 0.5;
    float2 p = (rel - offset) / (unit * max(abs(stretch), float2(0.01)));
    float3 q = float3(p + seed * float2(37.1, 17.3), evolution);
    float2 drift = parallax / unit;
    float nx = fbm(q, octaves, drift, 0.62) - 0.5 + bias * 0.5;
    float ny = fbm(q + float3(31.7, 47.3, 11.0), octaves, drift, 0.62) - 0.5 + bias * 0.5;
    float amount = 4.0 * strength * 0.4 * size.y;
    float2 d = float2(nx, ny) * amount;
    if (direction > 0.5 && direction < 1.5) d.y = 0.0;
    if (direction > 1.5 && direction < 2.5) d.x = 0.0;
    if (direction > 2.5) {
        float2 r = length(rel) > 0.001 ? normalize(rel) : float2(1.0, 0.0);
        d = direction < 3.5 ? r * nx * amount : float2(-r.y, r.x) * nx * amount;
    }
    return image.eval(coord + d);
}
